sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var inc = new x_1921506_incide_0.AssignmentEngine();
    // var res = inc.getAssignmentGroup(current.category);
    // var def = res.primaryGroup;
    // var bck = res.secondaryGroup;
    // gs.addInfoMessage(def);

    // var engine = new x_1921506_incide_0.AssignmentEngine();

    var result = inc.findEligibleAgentsWithFallback(current.getValue('category'), current.getValue('subcategory'), current.getValue('priority'));
    gs.addInfoMessage(result);
    gs.addInfoMessage(result.success);
    gs.addInfoMessage(result.eligibleAgent + 'before calling select best agent');
    if (result.success) {

        // Choose the best agent from the returned candidates
        var selectedAgent = inc.selectBestAgent(result.eligibleAgent, current.getValue('priority'));


        if (selectedAgent) {
            gs.addInfoMessage(result.groupSysId);
            gs.addErrorMessage(selectedAgent + 'after selected agent');

            if (current.priority == '1') {
                var log = inc.logAssignment(current.sys_id, result.groupSysId, selectedAgent, 'Agent selected based skill availability and workload', 'p1_override');

            } else {

                log = inc.logAssignment(current.sys_id, result.groupSysId, selectedAgent, 'Agent selected based skill availability and workload', 'initial');

            }
            current.setWorkflow(false);
            current.setValue('assignment_group', result.groupSysId);

            current.setValue('assigned_to', selectedAgent);
            current.update();



            gs.info('Auto-assignment successful. Fallback used: ' + result.fallbackUse);

        } else {

            gs.warn(
                'Eligible candidates were found, but no agent passed ' + 'the selection/capacity check.');

            var fal = inc.logAssignment(current.sys_id, result.groupSysId, '', 'No eligible agents found in default or backup group', 'Fallback_No Match');
        }

    } else {

        gs.warn('Auto-assignment failed: ' + result.reason);

        // Add your fallback_no_match logging and manager notification here.
    }



})(current, previous);
